from pwn import *

hex_bmp = ""
hex_bmp = hex_bmp[108:]
bmp = bytes.fromhex(hex_bmp)
l=93
padding = 4 - (l % 4)
full_l = l+padding
rows = []
for i in range(0,len(bmp),full_l):
    row = bmp[i:i+(full_l)]
    if len(row) < (full_l):
        break
    row = row[:l]
    row = row[::3]
    rows.append(row)

rows.reverse()

for r in rows:
    for i in [r[j:j+8] for j in range(0,len(row),8)]:
        if len(i) == 8 and i != b'\x00'*8:
            print(hex(u64(i)))
